package appserver

import (
	"context"
	"errors"
	"strings"
	"time"

	"github.com/blueberrycongee/wuu/internal/activity"
	"github.com/blueberrycongee/wuu/internal/providers"
	"github.com/blueberrycongee/wuu/internal/runtime"
	"github.com/blueberrycongee/wuu/internal/toolresult"
)

// external_artifact history rows are host-owned presentation records, excluded
// from engine history. ClientID is the Wuu turn ID; ToolCallID is generated by
// the host bridge, not an engine call ID. Name and DisplayContent hold the
// tool name and JSON arguments, ToolResult holds the complete result, and At is
// the publication time. The row sequence is its durable history address.
const externalArtifactHistoryRecord = "external_artifact"

func (s *Server) publishExternalArtifact(ctx context.Context, binding *runtime.State, th *threadState, turnID string, call providers.ToolCall, result toolresult.Result) error {
	if binding == nil || th == nil || call.ID == "" || call.Name != "present_artifact" {
		return errors.New("invalid external artifact publication")
	}
	now := time.Now().UTC()
	record := persistedMessage{Role: "meta", Content: externalArtifactHistoryRecord, ClientID: turnID, ToolCallID: call.ID, Name: call.Name, DisplayContent: call.Arguments, ToolResult: cloneToolResult(&result), At: now}
	th.streamMu.Lock()
	defer th.streamMu.Unlock()
	if err := activity.ControlErr(ctx); err != nil {
		return err
	}
	th.mu.Lock()
	if th.currentTurn != turnID || th.turnIndexLocked(turnID) < 0 {
		th.mu.Unlock()
		return errors.New("artifact turn is unavailable")
	}
	if th.PersistHistory {
		if binding.Sessions == nil {
			th.mu.Unlock()
			return errors.New("artifact history is unavailable")
		}
		if err := s.persistExternalArtifactPrefixLocked(binding, th, turnID, now); err != nil {
			th.mu.Unlock()
			return err
		}
		seq, err := binding.Sessions.AppendHistoryRecordReturningSeq(th.ID, historyRecordFromPersistedMessage(record))
		if err != nil {
			th.mu.Unlock()
			return err
		}
		record.Seq = seq
		th.historyHeadSeq = max(th.historyHeadSeq, seq)
	} else {
		_ = s.persistExternalArtifactPrefixLocked(nil, th, turnID, now)
	}
	batch := th.completeActiveAgentItemLocked(turnID, now, false)
	item := externalArtifactItem(th.nextItemIDLocked(turnID), record)
	th.upsertItemLocked(turnID, item, now)
	batch = append(batch, itemStarted(th.ID, turnID, item, now), itemCompleted(th.ID, turnID, item, now))
	th.mu.Unlock()
	s.notifyOutboundBatch(binding, batch)
	return nil
}

// persistExternalArtifactPrefixLocked writes assistant text emitted before an
// artifact as its own history row. Without this boundary the artifact row is
// appended first and replay merges all assistant text after it. The final
// engine message is trimmed at the same boundary during settlement.
func (s *Server) persistExternalArtifactPrefixLocked(binding *runtime.State, th *threadState, turnID string, now time.Time) error {
	if th.externalArtifactTurnID != turnID {
		th.externalArtifactTurnID = turnID
		th.externalArtifactText = ""
	}
	liveText := th.turnAgentTextLocked(turnID)
	if !strings.HasPrefix(liveText, th.externalArtifactText) {
		// A provider replaced streamed content instead of appending it. Keep
		// the artifact visible, but leave settlement unsplit rather than
		// persisting duplicate assistant text under an unknown boundary.
		th.externalArtifactTurnID = ""
		th.externalArtifactText = ""
		return nil
	}
	segment := liveText[len(th.externalArtifactText):]
	if segment == "" {
		return nil
	}
	seq := 0
	if binding != nil && th.PersistHistory {
		record := persistedMessage{Role: "assistant", Content: segment, At: now}
		var err error
		seq, err = binding.Sessions.AppendHistoryRecordReturningSeq(th.ID, historyRecordFromPersistedMessage(record))
		if err != nil {
			return err
		}
		th.historyHeadSeq = max(th.historyHeadSeq, seq)
	}
	th.History = append(th.History, providers.ChatMessage{Role: "assistant", Content: segment, Seq: seq})
	th.stampExternalArtifactPrefixLocked(turnID, segment, seq)
	th.externalArtifactText = liveText
	return nil
}

func (th *threadState) turnAgentTextLocked(turnID string) string {
	turnIndex := th.turnIndexLocked(turnID)
	if turnIndex < 0 {
		return ""
	}
	var text strings.Builder
	for _, item := range th.Turns[turnIndex].Items {
		if item.Type == ThreadItemAgentMessage {
			text.WriteString(item.Text)
		}
	}
	return text.String()
}

func (th *threadState) stampExternalArtifactPrefixLocked(turnID, segment string, seq int) {
	turnIndex := th.turnIndexLocked(turnID)
	if turnIndex < 0 {
		return
	}
	items := th.Turns[turnIndex].Items
	for i := len(items) - 1; i >= 0; i-- {
		if items[i].Type != ThreadItemAgentMessage || items[i].Text == "" {
			continue
		}
		if !strings.HasSuffix(segment, items[i].Text) {
			continue
		}
		if seq > 0 {
			items[i].Seq = seq
		}
		return
	}
}

// trimExternalArtifactMessagesLocked removes text already persisted before an
// artifact from the engine's aggregate assistant message. The remaining text
// is persisted after the artifact row, so restart and fork keep live order.
func (th *threadState) trimExternalArtifactMessagesLocked(turnID string, messages []providers.ChatMessage) []providers.ChatMessage {
	if th.externalArtifactTurnID != turnID || th.externalArtifactText == "" {
		return messages
	}
	remaining := th.externalArtifactText
	out := providers.CloneChatMessages(messages)
	for i := range out {
		if remaining == "" {
			break
		}
		if !strings.EqualFold(strings.TrimSpace(out[i].Role), "assistant") {
			continue
		}
		switch {
		case strings.HasPrefix(out[i].Content, remaining):
			out[i].Content = strings.TrimPrefix(out[i].Content, remaining)
			remaining = ""
		case strings.HasPrefix(remaining, out[i].Content):
			remaining = strings.TrimPrefix(remaining, out[i].Content)
			out[i].Content = ""
		default:
			return messages
		}
	}
	if remaining != "" {
		return messages
	}
	filtered := out[:0]
	for _, message := range out {
		if assistantMessageEmpty(message) {
			continue
		}
		filtered = append(filtered, message)
	}
	return filtered
}

func assistantMessageEmpty(message providers.ChatMessage) bool {
	return strings.EqualFold(strings.TrimSpace(message.Role), "assistant") &&
		strings.TrimSpace(message.Content) == "" &&
		strings.TrimSpace(message.ReasoningContent) == "" &&
		len(message.Images) == 0 && len(message.Files) == 0 && len(message.ContentParts) == 0 && len(message.ToolCalls) == 0
}

func externalArtifactItem(id string, record persistedMessage) ThreadItem {
	return ThreadItem{ID: id, Seq: record.Seq, SourceID: record.ToolCallID, Type: ThreadItemToolCall, Status: ThreadItemStatusCompleted, Name: record.Name, Arguments: record.DisplayContent, ResultDetail: cloneToolResult(record.ToolResult)}
}
